"""The player career's Test year: World Cup in the league format, the Ashes series, two points a win."""

def apply(js, rep, resub, replace_function):
    js = replace_function(js, 'tAdd', "function tAdd(T,a,b,x,y){const A=T[a],B=T[b];if(!A||!B)return;A.p++;B.p++;A.pf+=x;A.pa+=y;B.pf+=y;B.pa+=x;if(x>y){A.w++;B.l++;A.pts+=2}else if(y>x){B.w++;A.l++;B.pts+=2}else{A.d++;B.d++;A.pts+=1;B.pts+=1}}", 'tadd')
    js = replace_function(js, 'simTest', "function simTest(s,a,b,neutral,ko){const r=simpleTestResult(a,b,s);if(!neutral)r.x+=2;if(ko&&r.x===r.y){if(Math.random()<.5)r.x+=1;else r.y+=1}return r}", 'simtest')
    js = replace_function(js, 'simpleTestResult', "function simpleTestResult(a,b,s){const d=clamp(natStrength(a,s)-natStrength(b,s),-22,22),base=19+Math.abs(d)*.5,x=Math.max(0,Math.round(base+d*.7+gauss()*7)),y=Math.max(0,Math.round(base-d*.7+gauss()*7));return {x,y}}", 'simple')
    js = rep(js, "const teams=compTeams(W.comp,s).slice().sort((a,b)=>seeded(a+':'+W.comp+':'+cyc)-seeded(b+':'+W.comp+':'+cyc)),R=W.comp==='rc'&&!W.single?6:teams.length-1;W.teams=teams;W.rounds=rrSlots(teams,null,R,flip,W.comp,W.comp==='rc'&&!W.single);W.table=tTable(teams)",
             "const teams=compTeams(W.comp,s).slice().sort((a,b)=>seeded(a+':'+W.comp+':'+cyc)-seeded(b+':'+W.comp+':'+cyc)),R=teams.length%2?teams.length:teams.length-1;W.teams=teams;W.rounds=W.comp==='ashes'?[0,1,2].map(i=>[{a:s.year%8===1?'England':'Australia',b:s.year%8===1?'Australia':'England',round:i+1,comp:'ashes'}]):rrSlots(teams,null,R,flip,W.comp,false).filter(r=>r.length);W.table=tTable(teams)")
    js = rep(js, "else if(W.kind==='wc'){const pools=drawWCPools(s);W.pools=pools;W.table=tTable(NATIONS);W.rounds=[0,1,2].map(i=>[]);for(const [pn,teams] of Object.entries(pools))rr(teams).forEach((r,i)=>r.forEach(([a,b])=>W.rounds[i].push({a,b,pool:pn,round:i+1,comp:'wc'})))}",
             "else if(W.kind==='wc'){const pools=s.year===2026?copy(POOLS):drawWCPools(s);W.pools=pools;W.table=tTable(NATIONS);W.rounds=wcFixtures(pools).map(r=>r.map(f=>({...f,comp:'wc'})))}")
    js = rep(js, "if(W.kind==='wc'&&W.stage==='rounds'){const q=[],thirds=[];for(const [pn,teams] of Object.entries(W.pools)){const o=tSort(W.table,teams);q.push({t:o[0].name,seed:0,pool:pn,pts:o[0].pts},{t:o[1].name,seed:1,pool:pn,pts:o[1].pts});thirds.push({t:o[2].name,seed:2,pool:pn,pts:o[2].pts,diff:o[2].pf-o[2].pa})}thirds.sort((x,y)=>y.pts-x.pts||y.diff-x.diff);q.push(...thirds.slice(0,4));const top=q.filter(x=>x.seed===0),rest=q.filter(x=>x.seed!==0).reverse(),fx=[];for(const t of top){let j=rest.findIndex(x=>x.pool!==t.pool);if(j<0)j=0;const o=rest.splice(j,1)[0];fx.push({a:t.t,b:o.t,ko:'Round of 16',comp:'wc'})}for(let i=0;i<rest.length;i+=2)fx.push({a:rest[i].t,b:rest[i+1].t,ko:'Round of 16',comp:'wc'});W.rounds.push(fx);W.stage='ko';if(!fx.some(f=>f.a===N||f.b===N))W.out='Out in the pool stage';return}",
             "if(W.kind==='wc'&&W.stage==='rounds'){const G=wcGroups(W.pools),o=Object.values(G).map(ts=>tSort(W.table,ts)),fx=o.length===2?[{a:o[0][0].name,b:o[1][1].name,ko:'Semi-finals',comp:'wc'},{a:o[1][0].name,b:o[0][1].name,ko:'Semi-finals',comp:'wc'}]:o.flatMap((g,i)=>i%2?[]:[{a:g[0].name,b:(o[i+1]||o[0])[1].name,ko:'Quarter-finals',comp:'wc'},{a:(o[i+1]||o[0])[0].name,b:g[1].name,ko:'Quarter-finals',comp:'wc'}]);W.rounds.push(fx);W.stage='ko';if(!fx.some(f=>f.a===N||f.b===N))W.out='Out in the group stage';return}")
    js = rep(js, "next={'Round of 16':'Quarter-finals','Quarter-finals':'Semi-finals','Semi-finals':'Final'}[last[0].ko]", "next={'Quarter-finals':'Semi-finals','Semi-finals':'Final'}[last[0].ko]")
    js = js.replace("World Rugby Player of the Year nominee", "Golden Boot nominee").replace("World Rugby Player of the Year", "Golden Boot")
    js = js.replace("is Golden Boot!", "wins the Golden Boot!")
    return js
